// ========== Utilidades ==========
function redondear(num) {
  if (num === null || num === undefined || isNaN(num)) return 0;
  return Math.round(num * 100) / 100;
}

function getTipoReporte() {
  const hora = new Date().getHours();
  if (hora >= 5 && hora <= 10) return "Reporte de inicio de operaciones (mañana)";
  if (hora >= 19 || hora <= 3) return "Reporte de cierre de turno (noche)";
  return "Reporte de seguimiento de producción";
}

function parseNumerico(valor) {
  return Number(valor) || 0;
}

function parsePorcentaje(valor) {
  // Los porcentajes vienen como decimal (0.3865 = 38.65%)
  const num = parseNumerico(String(valor).replace('%', ''));
  return num * 100;   // Convertir a porcentaje real
}

function contarReferencias(refStr) {
  if (!refStr) return 0;
  const lineas = refStr.split('\n').map(x => x.trim()).filter(x => x && x.toLowerCase() !== 'sin datos');
  return lineas.length;
}

// ========== Mapeo de sinónimos de columnas ==========
const sinonimos = {
  maquina:           ["maquina"],
  programaciones:    ["programaciones relacionadas"],
  referencias:       ["referencias a producir"],
  kgProgramados:     ["kilogramos programado", "kilogramos programados", "kg programados", "kg programado"],
  kgAtrasados:       ["kilogramos atrasos", "kg atrasados", "atrasos"],
  kgAdelantados:     ["kilogramos adelantados futuro", "kg adelantados futuro"],
  kgAdelantadosHoy:  ["kilogramos adelanto hoy", "kg adelanto hoy", "adelanto hoy"],
  kgHechos:          ["kilos ya hechos", "kg hechos"],
  kgTotal:           ["total kilogramos a producir", "total kg a producir", "total kilogramos", "kg totales a producir"],
  horasTotales:      ["tiempo total", "horas totales", "horas estimadas"],
  cumplimiento:      ["% cumplimiento", "cumplimiento", "%cumplimiento", "cumplimiento (%)"],
  fueraCapacidad:    ["fuera de capacidad de produccion del turno", "fuera de capacidad", "exceso de capacidad", "sobrecarga (kg)", "kg fuera capacidad"]
};

function limpiarTexto(texto) {
  return texto.replace(/[\s\n]+/g, ' ').trim().toLowerCase();
}

function getValor(row, campoLogico) {
  const opciones = sinonimos[campoLogico];
  if (!opciones) return undefined;
  for (const key of Object.keys(row)) {
    const limpia = limpiarTexto(key);
    if (opciones.some(op => limpiarTexto(op) === limpia)) {
      return row[key];
    }
  }
  return undefined;
}

function extraerAreaDesdeMaquina(maquina) {
  const nombre = maquina.toLowerCase();
  if (nombre.includes('selladora')) return 'Sellado';
  if (nombre.includes('extrusora')) return 'Extrusión';
  if (nombre.includes('impresora')) return 'Impresión';
  return 'Sin área';
}

function calcularSalud(maquinasSobrecargadas, cumplimientoPromedio) {
  if (maquinasSobrecargadas > 5 || cumplimientoPromedio < 50) {
    return {
      nivel: "Crítico",
      mensaje: `Varias máquinas exceden su capacidad. Cumplimiento promedio del ${cumplimientoPromedio}%. Se requiere intervención inmediata.`
    };
  }
  if (maquinasSobrecargadas > 2 || cumplimientoPromedio < 70) {
    return {
      nivel: "Regular",
      mensaje: `${maquinasSobrecargadas} máquinas sobrecargadas. Cumplimiento promedio del ${cumplimientoPromedio}%.`
    };
  }
  return {
    nivel: "Bueno",
    mensaje: "Operación dentro de lo esperado."
  };
}

// ========== Variables principales ==========
const ahora = new Date();
const tipoReporte = getTipoReporte();

const areas = {};
const resumenPlanta = {
  maquinas_activas: 0,
  total_programaciones: 0,
  total_referencias: 0,
  kg_programados: 0,
  kg_atrasados: 0,
  kg_adelantados: 0,
  kg_totales_producir: 0,
  horas_totales_estimadas: 0,
  cumplimiento_sum: 0,
  cumplimiento_count: 0,
  maquinas_sobrecargadas: 0,
  kg_fuera_capacidad: 0
};
const alertas = [];

function inicializarArea(nombre) {
  return {
    area: nombre,
    maquinas_activas: 0,
    programaciones: 0,
    referencias: 0,
    kg_programados: 0,
    kg_atrasados: 0,
    kg_adelantados: 0,
    kg_totales: 0,
    horas_totales: 0,
    cumplimiento_sum: 0,
    cumplimiento_count: 0,
    maquinas_criticas: [],
    turnos: {
      A: { capacidad: 0, kilos: 0 },
      B: { capacidad: 0, kilos: 0 },
      C: { capacidad: 0, kilos: 0 }
    }
  };
}

function procesarFila(row) {
  const maquina = getValor(row, 'maquina');
  if (!maquina || maquina.toLowerCase().includes('total')) return;

  const areaNombre = extraerAreaDesdeMaquina(maquina);
  if (!areas[areaNombre]) {
    areas[areaNombre] = inicializarArea(areaNombre);
  }

  const programaciones = parseNumerico(getValor(row, 'programaciones'));
  const referencias = contarReferencias(getValor(row, 'referencias'));
  const kgProgramados = parseNumerico(getValor(row, 'kgProgramados'));
  const kgAtrasados = parseNumerico(getValor(row, 'kgAtrasados'));
  const kgAdelantados = parseNumerico(getValor(row, 'kgAdelantados'));
  const kgAdelantadosHoy = parseNumerico(getValor(row, 'kgAdelantadosHoy'));
  const kgTotal = parseNumerico(getValor(row, 'kgTotal'));
  const horasTotales = parseNumerico(getValor(row, 'horasTotales'));
  let cumplimiento = parsePorcentaje(getValor(row, 'cumplimiento'));  // ya en %
  let fueraCapacidad = parseNumerico(getValor(row, 'fueraCapacidad'));

  // Limpiar residuos flotantes muy pequeños
  if (fueraCapacidad < 0.01) fueraCapacidad = 0;

  // ----- Extraer turnos según el área -----
  const esExtrusion = maquina.toLowerCase().includes('extrusora');
  let turnoA_cap = 0, turnoA_kilos = 0;
  let turnoB_cap = 0, turnoB_kilos = 0;
  let turnoC_cap = 0, turnoC_kilos = 0;

  if (esExtrusion) {
    turnoA_cap = parseNumerico(row["Turno D"]);
    turnoA_kilos = parseNumerico(row["Kilos hechos Turno D"]);
    turnoB_cap = parseNumerico(row["Turno E"]);
    turnoB_kilos = parseNumerico(row["Kilos hechos Turno E"]);
  } else {
    turnoA_cap = parseNumerico(row["Turno A"]);
    turnoA_kilos = parseNumerico(row["Kilos hechos Turno A"]);
    turnoB_cap = parseNumerico(row["Turno B"]);
    turnoB_kilos = parseNumerico(row["Kilos hechos Turno B"]);
    turnoC_cap = parseNumerico(row["Turno C"]);
    turnoC_kilos = parseNumerico(row["Kilos hechos Turno C"]);
  }

  // Acumular en el área
  const area = areas[areaNombre];
  area.turnos.A.capacidad += turnoA_cap;
  area.turnos.A.kilos += turnoA_kilos;
  area.turnos.B.capacidad += turnoB_cap;
  area.turnos.B.kilos += turnoB_kilos;
  area.turnos.C.capacidad += turnoC_cap;
  area.turnos.C.kilos += turnoC_kilos;

  // --- Métricas globales ---
  const totalKilosArea = kgTotal + kgProgramados + kgAtrasados + kgAdelantados + kgAdelantadosHoy;
  if (totalKilosArea > 0) {
    resumenPlanta.maquinas_activas++;
    area.maquinas_activas++;
  }

  resumenPlanta.total_programaciones += programaciones;
  resumenPlanta.total_referencias += referencias;
  resumenPlanta.kg_programados += kgProgramados;
  resumenPlanta.kg_atrasados += kgAtrasados;
  resumenPlanta.kg_adelantados += kgAdelantados + kgAdelantadosHoy;   // Incluir adelanto hoy
  resumenPlanta.kg_totales_producir += kgTotal;
  resumenPlanta.horas_totales_estimadas += horasTotales;

  if (!isNaN(cumplimiento) && cumplimiento > 0) {
    resumenPlanta.cumplimiento_sum += cumplimiento;
    resumenPlanta.cumplimiento_count++;
  }

  if (fueraCapacidad > 0) {
    resumenPlanta.maquinas_sobrecargadas++;
    resumenPlanta.kg_fuera_capacidad += fueraCapacidad;
    alertas.push(`${maquina} excede capacidad (${redondear(fueraCapacidad)} kg)`);
    area.maquinas_criticas.push({
      maquina: maquina,
      kg_fuera_capacidad: redondear(fueraCapacidad)
    });
  }

  area.programaciones += programaciones;
  area.referencias += referencias;
  area.kg_programados += kgProgramados;
  area.kg_atrasados += kgAtrasados;
  area.kg_adelantados += kgAdelantados + kgAdelantadosHoy;
  area.kg_totales += kgTotal;
  area.horas_totales += horasTotales;
  if (!isNaN(cumplimiento) && cumplimiento > 0) {
    area.cumplimiento_sum += cumplimiento;
    area.cumplimiento_count++;
  }
}

for (const item of $input.all()) {
  procesarFila(item.json);
}

// ========== Cálculos finales ==========
const cumplimientoPromedio = resumenPlanta.cumplimiento_count
  ? Math.round(resumenPlanta.cumplimiento_sum / resumenPlanta.cumplimiento_count)
  : 0;

const salud = calcularSalud(resumenPlanta.maquinas_sobrecargadas, cumplimientoPromedio);

const areasFinal = Object.values(areas).map(a => ({
  area: a.area,
  maquinas_activas: a.maquinas_activas,
  programaciones: a.programaciones,
  referencias: a.referencias,
  kg_programados: redondear(a.kg_programados),
  kg_atrasados: redondear(a.kg_atrasados),
  kg_adelantados: redondear(a.kg_adelantados),
  kg_reales_producir_hoy: redondear(a.kg_totales),
  horas_totales: redondear(a.horas_totales),
  cumplimiento_promedio: a.cumplimiento_count
    ? Math.round(a.cumplimiento_sum / a.cumplimiento_count)
    : 0,
  maquinas_criticas: a.maquinas_criticas,
  turnos: {
    A: {
      capacidad: redondear(a.turnos.A.capacidad),
      kilos_hechos: redondear(a.turnos.A.kilos)
    },
    B: {
      capacidad: redondear(a.turnos.B.capacidad),
      kilos_hechos: redondear(a.turnos.B.kilos)
    },
    C: {
      capacidad: redondear(a.turnos.C.capacidad),
      kilos_hechos: redondear(a.turnos.C.kilos)
    }
  }
}));

// ========== Salida final ==========
return [{
  json: {
    tipo_reporte: tipoReporte,
    fecha: ahora.toISOString().split('T')[0],
    hora_generacion: ahora.toLocaleTimeString(),
    salud_general: salud,
    resumen_planta: {
      maquinas_activas: resumenPlanta.maquinas_activas,
      total_programaciones: resumenPlanta.total_programaciones,
      total_referencias: resumenPlanta.total_referencias,
      kg_programados: redondear(resumenPlanta.kg_programados),
      kg_atrasados: redondear(resumenPlanta.kg_atrasados),
      kg_adelantados: redondear(resumenPlanta.kg_adelantados),
      kg_reales_producir_hoy: redondear(resumenPlanta.kg_totales_producir),
      horas_totales_estimadas: redondear(resumenPlanta.horas_totales_estimadas),
      cumplimiento_promedio: cumplimientoPromedio,
      maquinas_sobrecargadas: resumenPlanta.maquinas_sobrecargadas,
      kg_fuera_capacidad: redondear(resumenPlanta.kg_fuera_capacidad)
    },
    por_area: areasFinal,
    alertas
  }
}];

return [
  {
    "hoja" : "Programador Planta Sellado"
  },
  {
    "hoja" : "Programador Planta Extrusion"
  },
  {
    "hoja" : "Programador Planta Impresión"
  }
]
